/// Represents the header information extracted from a Minecraft Bedrock Edition game packet.
///
/// This includes the packet's unique ID and the source/destination subclient IDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GameHeader {
    pub id: McpePacketName,
    pub from_subclient: u32,
    pub to_subclient: u32,
}
#[derive(Debug, Clone)]
pub struct McpePacketArgs;
#[derive(Debug, Clone, PartialEq)]
pub struct OpaquePacket {
    pub id: McpePacketName,
    pub payload: bytes::Bytes,
}
impl OpaquePacket {
    pub fn new(
        id: McpePacketName,
        payload: bytes::Bytes,
    ) -> Result<Self, crate::bedrock::error::DecodeError> {
        if !id.is_opaque() {
            return Err(crate::bedrock::error::DecodeError::InvalidPacketId { id: id as u32 });
        }
        Ok(Self { id, payload })
    }
}
impl crate::bedrock::codec::BedrockSized for OpaquePacket {
    fn encoded_size(&self) -> usize {
        self.payload.len()
    }
}
